import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def extract(data):
    pkgs = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (name, tfm, pkg['id'])
                pkgs[key] = pkg['resolvedVersion']
    return pkgs

bp = extract(b)
ap = extract(a)
changes = []
for k in sorted(set(bp)|set(ap)):
    bv = bp.get(k, 'N/A')
    av = ap.get(k, 'N/A')
    if bv != av:
        changes.append((k[0], k[1], k[2], bv, av))

if changes:
    print('CHANGES:')
    for c in changes:
        print(f'  {c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]}')
else:
    print('NO CHANGES - all packages resolve identically')
print(f'Total packages compared: {len(bp)}')
"

